class Vehicle {
  move() {
    return 'Moving forward';
  }
}

class Car extends Vehicle {
  honk() {
    return 'Beep beep';
  }
}

const myCar = new Car();
console.log(myCar.move());
console.log(myCar.honk());

concepts.codeExample:
class CoffeeMachine {
  brew() {
    this.#heatWater();
    this.#prepareFilter();
    return 'Coffee is ready';
  }

  #heatWater() {
    return 'Heating water';
  }

  #prepareFilter() {
    return 'Preparing filter';
  }
}

const machine = new CoffeeMachine();
console.log(machine.brew());

concepts.tryItCode:
class PaymentProcessor {
  pay() {
    this.#validate();
    return this.#sendRequest();
  }

  #validate() {
    return true;
  }

  #sendRequest() {
    return 'Payment complete';
  }
}

const processor = new PaymentProcessor();
console.log(processor.pay());
